void Update()
{
    if (timer >= timeForCustomers || givefoodtocustomers.GoToNextCustomer == true)
    {
        //make sure the customers dont keep switching
        givefoodtocustomers.GoToNextCustomer = false;
        timer = 0f;

        // Deactivate the previous customer before choosing a new one
        CHOSENcustomer.SetActive(false);

        // Randomly choose a meal and customer
        randomMeel = Random.Range(1, 7); // Between 1 and 6
        randomCustomer = Random.Range(1, 8); // Between 1 and 7 (you have 7 customers)

        // Select the customer based on randomCustomer value
        switch (randomCustomer)
        {
            case 1:
                CHOSENcustomer = Customer1;
                break;
            case 2:
                CHOSENcustomer = Customer2;
                break;
            case 3:
                CHOSENcustomer = Customer3;
                break;
            case 4:
                CHOSENcustomer = Customer4;
                break;
            case 5:
                CHOSENcustomer = Customer5;
                break;
            case 6:
                CHOSENcustomer = Customer6;
                break;
            case 7:
                CHOSENcustomer = Customer7;
                break;

            default:
                Debug.Log("Random customer was out of bounds");
                break;
        }

        // Handle meal logic
        switch (randomMeel)
        {
            case 1:
                // cake
                CHOSenMeal = 1;
                mealText.text = "Ik wil een taart!";
                break;
            case 2:
                // sandwich
                CHOSenMeal = 2;
                mealText.text = "Ik wil een broodje...";
                break;
            case 3:
                // bagel
                CHOSenMeal= 3;
                mealText.text = "Mag ik een bagel?";
                break;
            case 4:
                // drink 1
                CHOSenMeal = 4;
                mealText.text = "Drankje 1 alsjeblieft!";
                break;
            case 5:
                // drink 2
                CHOSenMeal = 5;
                mealText.text = "HMMM, drankje 2 ziet er wel goed uit.";
                break;
            case 6:
                // drink 3
                CHOSenMeal = 6;
                mealText.text = "Zou ik drankje 3 mogen proberen?";
                break;
            default:
                Debug.Log("Random meal was out of bounds");
                break;
        }

        // Activate the newly selected customer
        CHOSENcustomer.SetActive(true);
    }
}

