private void SpawnFood(GameObject foodOBJ)
{
    //delete items on plates when food is spawned
    Destroy(plate1.HeldItem.gameObject);
    Destroy(plate2.HeldItem.gameObject);
    Destroy(plate3.HeldItem.gameObject);
    Destroy(plate4.HeldItem.gameObject);

    //make sure they are deleted
    plate1.HeldItem = null;
    plate2.HeldItem = null;
    plate3.HeldItem = null;
    plate4.HeldItem = null;

    //spawn the food
    Instantiate(foodOBJ, foodTransform.position, foodTransform.rotation);
}

public void OnSelectEntered(SelectEnterEventArgs args)
{
    grabbed = true;
    rb.isKinematic = true;
}

public void OnSelectExited(SelectExitEventArgs args)
{
    grabbed = false;
    rb.isKinematic = false;
}

void Update()
{
    switch(state)
    {
        case Idle:
            LookForPlayer();
            break;

        case Chase:
            MoveTowardPlayer();
            break;

        case Attack:
            TryShoot();
            break;
    }
}

void Shoot()
{
    Ray ray = new Ray(transform.position, transform.forward);

    if (Physics.Raycast(ray, out var hit, 50f))
    {
        Debug.Log($"Hit {hit.collider.name}");
    }
}

